export function sheetGeom(slug: string): SheetGeom | undefined {
  return GEOM[slug];
}

export function sheetFill(
  slug: string,
  row: number,
  visColIdx: number,
): string | undefined {
  const g = GEOM[slug];
  const line = g?.rows[row];
  if (!g || !line) return undefined;
  const idx = ALPHABET.indexOf(line[visColIdx] ?? "0");
  return idx > 0 ? g.p[idx] : undefined;
}

export function sheetSurface(slug: string): string | undefined {
  return GEOM[slug]?.surface;
}

export type SheetTypo = {
  h: "left" | "center" | "right" | null;
  v: "top" | "center" | "bottom" | null;
  sz: number;
  b: boolean;
  c: string | null;
};

export function sheetTypo(
  slug: string,
  row: number,
  visColIdx: number,
): SheetTypo | undefined {
  const g = GEOM[slug];
  const line = g?.trows?.[row];
  if (!g?.tp || !line) return undefined;
  const idx = ALPHABET.indexOf(line[visColIdx] ?? "0");
  if (idx <= 0) return undefined;
  const t = g.tp[idx - 1];
  return t
    ? {
        h: t[0] as SheetTypo["h"],
        v: t[1] as SheetTypo["v"],
        sz: t[2],
        b: t[3] === 1,
        c: t[4] ?? null,
      }
    : undefined;
}

export type SheetMerge = {
  r1: number;
  c1: number;
  r2: number;
  c2: number;
};

// Workbook-authored merges, clipped to the rendered window. Returns null
// when the workbook declares no merge for the cell, undefined when the
// sheet carries no merge data at all (then the model's list applies).
export function sheetMerge(
  slug: string,
  row: number,
  col: number,
): SheetMerge | null | undefined {
  const list = GEOM[slug]?.merges;
  if (list === undefined) return undefined;
  for (const m of list) {
    if (row >= m[0] && row <= m[2] && col >= m[1] && col <= m[3])
      return { r1: m[0], c1: m[1], r2: m[2], c2: m[3] };
  }
  return null;
}

// Raw workbook merge list, clipped to the rendered window. undefined means
// no workbook merge data; an empty list means genuinely none.
export function sheetMerges(
  slug: string,
): [number, number, number, number][] | undefined {
  return GEOM[slug]?.merges;
}

// Painted prefix of the rendered window: only the first pageR rows and
// pageC columns fall inside the LO page. Cells past that are dead space.
export function sheetPage(
  slug: string,
): { rows: number; cols: number } | undefined {
  const g = GEOM[slug];
  return g?.pageR === undefined || g.pageC === undefined
    ? undefined
    : { rows: g.pageR, cols: g.pageC };
}
